        else: print(pre+'  options type', type(opts).__name__)
    if inp.get('type')=='conditional':
        tp=inp.get('test_param',{})
        print(pre+f\"  test_param {tp.get('name')} type={tp.get('type')} label={tp.get('label')}\")
        if tp.get('options'): print(pre+'  test options', tp.get('options'))
        for case in inp.get('cases', []):
            print(pre+f\"  case value={case.get('value')}\")
            for ci in case.get('inputs', []): summarize(ci, indent+2)
    if inp.get('inputs'):
        for ci in inp.get('inputs'): summarize(ci, indent+1)

print('name', t.get('name'), 'version', t.get('version'))
for inp in t.get('inputs', []): summarize(inp)
print('outputs:')
for out in t.get('outputs', []): print(out)
